<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Kiểm tra hồ sơ</title><style>
*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f8fafc;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.card{width:min(390px,100%);text-align:center}.scene{position:relative;width:240px;height:220px;margin:auto}.glow{position:absolute;width:165px;height:165px;left:50%;top:48%;transform:translate(-50%,-50%);border-radius:50%;background:#eff6ff;filter:blur(2px);animation:glow 2.2s ease-in-out infinite}.shadow{position:absolute;width:112px;height:18px;left:50%;bottom:21px;transform:translateX(-50%);border-radius:50%;background:#0f172214;filter:blur(7px)}.paper{position:absolute;width:116px;height:148px;left:62px;top:25px;border-radius:14px;border:2px solid #dbe4f0;background:#f1f5f9}.p1{transform:rotate(-11deg) translate(-3px,4px)}.p2{transform:rotate(9deg) translate(4px,2px)}.doc{position:absolute;z-index:4;width:124px;height:156px;left:58px;top:17px;background:#fff;border:2px solid #cbd5e1;border-radius:15px;box-shadow:0 24px 48px #0f17221a;overflow:hidden}.doc:before{content:'';position:absolute;left:22px;top:33px;width:82px;height:5px;border-radius:5px;background:#bfdbfe;box-shadow:0 16px #dbeafe,0 32px #dbeafe}.scan{position:absolute;z-index:5;left:0;width:100%;height:45px;background:linear-gradient(transparent,#3b82f62e,transparent);animation:scan 2.4s ease-in-out infinite}.badge{position:absolute;z-index:8;right:11px;bottom:8px;width:43px;height:43px;display:grid;place-items:center;border-radius:50%;background:#fff;border:1px solid #dbeafe;box-shadow:0 8px 18px #2563eb29}.bars{display:flex;align-items:flex-end;gap:3px;height:17px}.bars i{width:3px;border-radius:5px;background:#3b82f6;animation:bars 1.1s ease-in-out infinite}.bars i:nth-child(1){height:8px}.bars i:nth-child(2){height:14px;animation-delay:.15s}.bars i:nth-child(3){height:10px;animation-delay:.3s}.result{display:none;position:absolute;z-index:9;left:50%;top:52%;transform:translate(-50%,-50%);width:76px;height:76px;border-radius:50%;background:#fff;border:2px solid;place-items:center;font-size:50px;font-weight:800;animation:pop .65s both}.status{font-size:22px;font-weight:750;color:#334155;margin-top:5px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#3b82f6;box-shadow:0 0 0 5px #3b82f61f;margin-right:9px}.desc{margin:10px auto 0;max-width:330px;font-size:14px;line-height:1.6;color:#64748b}.progress{width:180px;height:4px;margin:20px auto;border-radius:10px;background:#e8eef7;overflow:hidden}.progress i{display:block;width:38%;height:100%;background:#3b82f6;animation:progress 2.2s infinite}.success .glow{background:#ecfdf5}.success .doc{border-color:#86efac}.success .result{display:grid;color:#16a34a;border-color:#86efac}.failed .glow{background:#fff7ed}.failed .doc{border-color:#fdba74;animation:sad .65s 1}.failed .result{display:grid;color:#f97316;border-color:#fdba74}@keyframes scan{0%{top:-50px;opacity:0}15%,75%{opacity:1}100%{top:145px;opacity:0}}@keyframes bars{50%{transform:scaleY(1.15);opacity:1}}@keyframes progress{from{transform:translateX(-150%)}to{transform:translateX(400%)}}@keyframes glow{50%{transform:translate(-50%,-50%) scale(1.06)}}@keyframes pop{from{opacity:0;transform:translate(-50%,-50%) scale(.25)}to{opacity:1;transform:translate(-50%,-50%) scale(1)}}@keyframes sad{20%{transform:translateX(-6px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}}
</style></head><body><main id="app" class="card"><div class="scene"><div class="glow"></div><div class="shadow"></div><div class="paper p1"></div><div class="paper p2"></div><div class="doc"><div class="scan"></div><div class="badge"><span class="bars"><i></i><i></i><i></i></span></div></div><div id="result" class="result"></div></div><div id="status" class="status"><span class="dot"></span>Đang kiểm tra</div><p id="desc" class="desc">Vui lòng đợi trong giây lát...</p><div id="progress" class="progress"><i></i></div></main><script>
(()=>{const url=@json($statusUrl),app=document.getElementById('app'),result=document.getElementById('result'),status=document.getElementById('status'),desc=document.getElementById('desc'),progress=document.getElementById('progress');let running=false,done=false;function outcome(ok){app.classList.remove('success','failed');app.classList.add(ok?'success':'failed');result.style.display='grid';result.textContent=ok?'✓':'☹';progress.hidden=true;status.innerHTML='<span class="dot"></span>'+(ok?'Hồ sơ đủ điều kiện':'Rất tiếc!');desc.textContent=ok?'Hồ sơ của bạn đủ điều kiện. Bạn sẽ được chuyển sang FE Online 2.0 sau 1–2 giây.':'Rất tiếc hồ sơ của Khách hàng không thoả điều kiện.'}async function check(){if(running||done)return;running=true;try{const r=await fetch(url,{headers:{Accept:'application/json'},cache:'no-store'});if(!r.ok)throw 0;const data=await r.json();if(data.state==='eligible'&&data.redirect_url){outcome(true);done=true;setTimeout(()=>location.replace(data.redirect_url),1500);return}if(data.state==='completed'){outcome(false);done=true;return}}catch(_){desc.textContent='Đang kết nối lại, vui lòng đợi...'}finally{running=false}setTimeout(check,1000)}check()})();
</script></body></html>
